package com.souls;

/** Tiny expression evaluator: + - * / ( ) and k/m/b suffixes, e.g. "2.5m*3 - 400k". */
final class Calc
{
	private final String s;
	private int pos;

	private Calc(String s)
	{
		this.s = s;
	}

	static double eval(String input)
	{
		Calc c = new Calc(input.toLowerCase().replace(",", "").replace(" ", "").replace('x', '*'));
		double v = c.expr();
		if (c.pos != c.s.length())
		{
			throw new IllegalArgumentException("Unexpected: " + c.s.charAt(c.pos));
		}
		return v;
	}

	private double expr()
	{
		double v = term();
		while (pos < s.length() && (s.charAt(pos) == '+' || s.charAt(pos) == '-'))
		{
			char op = s.charAt(pos++);
			double r = term();
			v = op == '+' ? v + r : v - r;
		}
		return v;
	}

	private double term()
	{
		double v = factor();
		while (pos < s.length() && (s.charAt(pos) == '*' || s.charAt(pos) == '/'))
		{
			char op = s.charAt(pos++);
			double r = factor();
			v = op == '*' ? v * r : v / r;
		}
		return v;
	}

	private double factor()
	{
		if (pos >= s.length())
		{
			throw new IllegalArgumentException("Unexpected end");
		}
		char c = s.charAt(pos);
		if (c == '-')
		{
			pos++;
			return -factor();
		}
		if (c == '(')
		{
			pos++;
			double v = expr();
			if (pos >= s.length() || s.charAt(pos) != ')')
			{
				throw new IllegalArgumentException("Missing )");
			}
			pos++;
			return v;
		}
		int start = pos;
		while (pos < s.length() && (Character.isDigit(s.charAt(pos)) || s.charAt(pos) == '.'))
		{
			pos++;
		}
		if (start == pos)
		{
			throw new IllegalArgumentException("Number expected");
		}
		double v = Double.parseDouble(s.substring(start, pos));
		if (pos < s.length())
		{
			char suf = s.charAt(pos);
			if (suf == 'k') { v *= 1_000; pos++; }
			else if (suf == 'm') { v *= 1_000_000; pos++; }
			else if (suf == 'b') { v *= 1_000_000_000; pos++; }
		}
		return v;
	}
}

package com.souls;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(SoulsConfig.GROUP)
public interface SoulsConfig extends Config
{
	String GROUP = "souls";

	@ConfigItem(keyName = "showOverlay", name = "Show on-screen total", description = "Show the soul total on screen", position = 1)
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(keyName = "multiplier", name = "Souls per combat level", description = "Souls gained per level of the monster killed", position = 2)
	default int multiplier()
	{
		return 10;
	}
}

package com.souls;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import net.runelite.api.Point;
import java.text.NumberFormat;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

public class SoulsOverlay extends Overlay
{
	private final SoulsPlugin plugin;
	private final SoulsConfig config;

	@Inject
	private SoulsOverlay(SoulsPlugin plugin, SoulsConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.showOverlay() || plugin.getIcon() == null)
		{
			return null;
		}
		String text = NumberFormat.getIntegerInstance().format(plugin.getTotal());
		g.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics fm = g.getFontMetrics();
		int size = 20;
		int gap = 4;

		g.drawImage(plugin.getIcon(), 0, 0, null);
		int textY = (size + fm.getAscent() - fm.getDescent()) / 2;
		OverlayUtil.renderTextLocation(g, new Point(size + gap, textY), text, Color.WHITE);

		return new Dimension(size + gap + fm.stringWidth(text), size);
	}
}

package com.souls;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.GridLayout;
import java.awt.image.BufferedImage;
import java.text.NumberFormat;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingConstants;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

public class SoulsPanel extends PluginPanel
{
	private final SoulsPlugin plugin;
	private final JLabel totalLabel = new JLabel("0", SwingConstants.CENTER);
	private final JTextField amountField = new JTextField("1000");
	private final JTextField setField = new JTextField();
	private final JTextField calcField = new JTextField();
	private final JLabel calcResult = new JLabel("= ", SwingConstants.CENTER);
	private final JLabel message = new JLabel(" ", SwingConstants.CENTER);

	public SoulsPanel(SoulsPlugin plugin, BufferedImage icon)
	{
		super();
		this.plugin = plugin;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));

		totalLabel.setIcon(new ImageIcon(icon));
		totalLabel.setFont(totalLabel.getFont().deriveFont(22f));
		totalLabel.setBorder(BorderFactory.createEmptyBorder(0, 0, 10, 0));
		add(totalLabel);

		// --- Quick adjust with arrows ---
		JButton up = new JButton("\u25B2");
		JButton down = new JButton("\u25BC");
		up.setToolTipText("Add souls");
		down.setToolTipText("Spend souls");
		up.addActionListener(e -> apply(parseField(amountField), 1));
		down.addActionListener(e -> apply(parseField(amountField), -1));
		JPanel arrows = new JPanel(new GridLayout(1, 2, 4, 0));
		arrows.add(down);
		arrows.add(up);
		JPanel adjustRow = new JPanel(new BorderLayout(6, 0));
		adjustRow.add(amountField, BorderLayout.CENTER);
		adjustRow.add(arrows, BorderLayout.EAST);
		add(section("Adjust by (k / m / b allowed)", adjustRow));

		// --- Set exact total ---
		JButton set = new JButton("Set");
		set.addActionListener(e ->
		{
			Long v = parseField(setField);
			if (v != null)
			{
				plugin.setTotal(v);
				setField.setText("");
				info(" ");
			}
		});
		JPanel setRow = new JPanel(new BorderLayout(6, 0));
		setRow.add(setField, BorderLayout.CENTER);
		setRow.add(set, BorderLayout.EAST);
		add(section("Set total", setRow));

		// --- Calculator ---
		JButton sub = new JButton("\u2212 Spend");
		JButton addBtn = new JButton("+ Add");
		sub.addActionListener(e -> apply(parseField(calcField), -1));
		addBtn.addActionListener(e -> apply(parseField(calcField), 1));
		JPanel calcButtons = new JPanel(new GridLayout(1, 2, 4, 0));
		calcButtons.add(sub);
		calcButtons.add(addBtn);
		JPanel calc = new JPanel();
		calc.setLayout(new BoxLayout(calc, BoxLayout.Y_AXIS));
		calc.add(calcField);
		calc.add(Box.createVerticalStrut(4));
		calc.add(calcResult);
		calc.add(Box.createVerticalStrut(4));
		calc.add(calcButtons);
		calcField.getDocument().addDocumentListener(new DocumentListener()
		{
			public void insertUpdate(DocumentEvent e) { updateCalc(); }
			public void removeUpdate(DocumentEvent e) { updateCalc(); }
			public void changedUpdate(DocumentEvent e) { updateCalc(); }
		});
		add(section("Calculator, e.g. 2.5m*3 - 400k", calc));

		message.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
		add(message);
	}

	public void refresh(long total)
	{
		totalLabel.setText(NumberFormat.getIntegerInstance().format(total));
	}

	private void apply(Long amount, int sign)
	{
		if (amount == null)
		{
			return;
		}
		info(" ");
		plugin.addSouls(sign * amount);
	}

	private Long parseField(JTextField field)
	{
		try
		{
			double v = Calc.eval(field.getText());
			if (Double.isNaN(v) || Double.isInfinite(v))
			{
				throw new IllegalArgumentException();
			}
			return Math.round(v);
		}
		catch (RuntimeException ex)
		{
			info("Couldn't read that number");
			return null;
		}
	}

	private void updateCalc()
	{
		String t = calcField.getText().trim();
		if (t.isEmpty())
		{
			calcResult.setText("= ");
			return;
		}
		try
		{
			calcResult.setText("= " + NumberFormat.getIntegerInstance().format(Math.round(Calc.eval(t))));
		}
		catch (RuntimeException ex)
		{
			calcResult.setText("= ?");
		}
	}

	private void info(String s)
	{
		message.setText(s);
	}

	private static JPanel section(String title, JPanel content)
	{
		JPanel p = new JPanel(new BorderLayout(0, 4));
		p.setBorder(BorderFactory.createEmptyBorder(6, 0, 6, 0));
		JLabel l = new JLabel(title);
		l.setForeground(Color.LIGHT_GRAY);
		p.add(l, BorderLayout.NORTH);
		p.add(content, BorderLayout.CENTER);
		return p;
	}
}

package com.souls;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.NpcDespawned;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@PluginDescriptor(
	name = "Souls",
	description = "Track souls earned from kills and spent like gold",
	tags = {"souls", "challenge", "counter"}
)
public class SoulsPlugin extends Plugin
{
	private static final String TOTAL_KEY = "total";

	@Inject
	private Client client;
	@Inject
	private ClientToolbar clientToolbar;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private SoulsOverlay overlay;
	@Inject
	private ConfigManager configManager;
	@Inject
	private SoulsConfig config;

	private SoulsPanel panel;
	private NavigationButton navButton;
	private BufferedImage icon;
	private long total;
	private final Set<NPC> engaged = new HashSet<>();

	@Override
	protected void startUp()
	{
		Long saved = configManager.getConfiguration(SoulsConfig.GROUP, TOTAL_KEY, Long.class);
		total = saved == null ? 0 : saved;

		icon = ImageUtil.resizeImage(ImageUtil.loadImageResource(SoulsPlugin.class, "soul_icon.png"), 20, 20);

		panel = new SoulsPanel(this, icon);
		panel.refresh(total);

		navButton = NavigationButton.builder()
			.tooltip("Souls")
			.icon(ImageUtil.resizeImage(icon, 16, 16))
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		overlayManager.remove(overlay);
		engaged.clear();
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied e)
	{
		if (e.getActor() instanceof NPC && e.getHitsplat().isMine())
		{
			engaged.add((NPC) e.getActor());
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath e)
	{
		if (!(e.getActor() instanceof NPC))
		{
			return;
		}
		NPC npc = (NPC) e.getActor();
		if (engaged.remove(npc))
		{
			int level = npc.getCombatLevel();
			if (level > 0)
			{
				addSouls((long) level * config.multiplier());
			}
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned e)
	{
		engaged.remove(e.getNpc());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOADING)
		{
			engaged.clear();
		}
	}

	public void addSouls(long delta)
	{
		setTotal(total + delta);
	}

	public void setTotal(long value)
	{
		total = Math.max(0, value);
		configManager.setConfiguration(SoulsConfig.GROUP, TOTAL_KEY, total);
		if (panel != null)
		{
			SwingUtilities.invokeLater(() -> panel.refresh(total));
		}
	}

	public long getTotal()
	{
		return total;
	}

	public BufferedImage getIcon()
	{
		return icon;
	}

	@Provides
	SoulsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SoulsConfig.class);
	}
}

